/// Label removal tests
///
/// This test file verifies the label removal functionality for bead-forge.

#[cfg(test)]
mod label_removal_tests {
    use bead_forge::model::Issue;
    use bead_forge::storage::sqlite::SqliteStore;
    use tempfile::TempDir;

    /// Test removing a single label from an issue
    #[test]
    fn test_remove_single_label() {
        let temp_dir = TempDir::new().unwrap();
        let store = SqliteStore::new(temp_dir.path().join("test.db")).unwrap();

        // Create an issue with labels
        let mut issue = Issue::new("test-1".to_string(), "Test Issue".to_string());
        issue.labels = vec!["phase-1".to_string(), "urgent".to_string(), "test3".to_string()];
        store.create_issue(&issue).unwrap();

        // Remove one label
        store.remove_label("test-1", "test3").unwrap();

        // Verify the label was removed
        let retrieved = store.get_issue("test-1").unwrap();
        assert_eq!(retrieved.labels, vec!["phase-1".to_string(), "urgent".to_string()]);
    }

    /// Test removing multiple labels at once
    #[test]
    fn test_remove_multiple_labels() {
        let temp_dir = TempDir::new().unwrap();
        let store = SqliteStore::new(temp_dir.path().join("test.db")).unwrap();

        // Create an issue with multiple labels
        let mut issue = Issue::new("test-2".to_string(), "Test Issue".to_string());
        issue.labels = vec!["phase-1".to_string(), "urgent".to_string(), "test3".to_string(), "extra".to_string()];
        store.create_issue(&issue).unwrap();

        // Remove multiple labels
        store.remove_label("test-2", "test3").unwrap();
        store.remove_label("test-2", "extra").unwrap();

        // Verify the labels were removed
        let retrieved = store.get_issue("test-2").unwrap();
        assert_eq!(retrieved.labels, vec!["phase-1".to_string(), "urgent".to_string()]);
    }

    /// Test removing all labels from an issue
    #[test]
    fn test_remove_all_labels() {
        let temp_dir = TempDir::new().unwrap();
        let store = SqliteStore::new(temp_dir.path().join("test.db")).unwrap();

        // Create an issue with labels
        let mut issue = Issue::new("test-3".to_string(), "Test Issue".to_string());
        issue.labels = vec!["phase-1".to_string(), "urgent".to_string()];
        store.create_issue(&issue).unwrap();

        // Remove all labels
        store.remove_label("test-3", "phase-1").unwrap();
        store.remove_label("test-3", "urgent").unwrap();

        // Verify no labels remain
        let retrieved = store.get_issue("test-3").unwrap();
        assert!(retrieved.labels.is_empty());
    }

    /// Test removing a non-existent label (should be idempotent)
    #[test]
    fn test_remove_nonexistent_label() {
        let temp_dir = TempDir::new().unwrap();
        let store = SqliteStore::new(temp_dir.path().join("test.db")).unwrap();

        // Create an issue with labels
        let mut issue = Issue::new("test-4".to_string(), "Test Issue".to_string());
        issue.labels = vec!["phase-1".to_string(), "urgent".to_string()];
        store.create_issue(&issue).unwrap();

        // Try to remove a label that doesn't exist
        store.remove_label("test-4", "nonexistent").unwrap();

        // Verify existing labels are unchanged
        let retrieved = store.get_issue("test-4").unwrap();
        assert_eq!(retrieved.labels, vec!["phase-1".to_string(), "urgent".to_string()]);
    }

    /// Test that label removal creates appropriate events
    #[test]
    fn test_label_removal_creates_events() {
        let temp_dir = TempDir::new().unwrap();
        let store = SqliteStore::new(temp_dir.path().join("test.db")).unwrap();

        // Create an issue with labels
        let mut issue = Issue::new("test-5".to_string(), "Test Issue".to_string());
        issue.labels = vec!["phase-1".to_string(), "urgent".to_string()];
        store.create_issue(&issue).unwrap();

        // Remove a label
        store.remove_label("test-5", "urgent").unwrap();

        // Verify a label_removed event was created
        let events = store.get_events("test-5").unwrap();
        assert!(events.iter().any(|e| matches!(e.event_type, bead_forge::model::EventType::LabelRemoved)));
    }
}
